  "code": "from marshmallow.error_store import ErrorStore, SCHEMA


class TestErrorStore:
    def test_init(self):
        error_store = ErrorStore()
        assert error_store.errors == {}

    def test_store_error_with_string(self):
        error_store = ErrorStore()
        error_store.store_error("error1")
        assert error_store.errors == {SCHEMA: "error1"}

    def test_store_error_with_list(self):
        error_store = ErrorStore()
        error_store.store_error(["error1", "error2"])
        assert error_store.errors == {SCHEMA: ["error1", "error2"]}

    def test_store_error_with_dict(self):
        error_store = ErrorStore()
        error_store.store_error({"field1": "error1"})
        assert error_store.errors == {"field1": "error1"}

    def test_store_error_with_field_name(self):
        error_store = ErrorStore()
        error_store.store_error("error1", field_name="field1")
        assert error_store.errors == {"field1": "error1"}

    def test_store_error_with_index(self):
        error_store = ErrorStore()
        error_store.store_error("error1", index=0)
        assert error_store.errors == {0: {SCHEMA: "error1"}}

    def test_store_error_with_field_name_and_index(self):
        error_store = ErrorStore()
        error_store.store_error("error1", field_name="field1", index=0)
        assert error_store.errors == {0: {"field1": "error1"}}

    def test_store_error_with_existing_field(self):
        error_store = ErrorStore()
        error_store.store_error("error1", field_name="field1")
        error_store.store_error("error2", field_name="field1")
        assert error_store.errors == {"field1": ["error1", "error2"]}

